LOCAL = {'A': 'alpha', 'B': 'beta', 'C': 'gamma'}
RULES = {
    'A': [('beta', 'B')],
    'B': [('gamma', 'C'), ('omega', 'A')],
    'C': [('omega', 'B')],
}


def route(start, destination, budget):
    if start not in LOCAL:
        raise ValueError('unknown starting node')
    if not isinstance(budget, int) or budget < 0:
        raise ValueError('budget must be a nonnegative integer')

    node = start
    trace = [node]
    while True:
        if destination == LOCAL[node]:
            return 'delivered', node, budget, trace

        next_node = next((target for tag, target in RULES[node]
                          if tag == destination), None)
        if next_node is None:
            return 'parked', node, budget, trace
        if budget == 0:
            return 'budget-exhausted', node, budget, trace

        budget -= 1
        node = next_node
        trace.append(node)
